#include <array>
#include <algorithm>
#include <functional>

int main() {
    std::array<int, 5> a = {1, 2, 3, 4, 5};

    // Use algorithm requiring Random Access Iterators
    std::reverse(a.begin(), a.end());

    // Use algorithm requiring output iterators and transformation
    std::transform(a.begin(), a.end(), 
                   a.begin(), 
                   std::negate<int>());

    // a now contains {-5, -4, -3, -2, -1}
    return a[0];
}
